/// Representation of a userlist that is generated by a rule.
class GoogleAdsSearchads360V23CommonRuleBasedUserListInfo {
  /// Flexible rule representation of visitors with one or multiple actions.
  ///
  /// The flexible user list is defined by two lists of operands –
  /// inclusive_operands and exclusive_operands; each operand represents a set
  /// of users based on actions they took in a given timeframe. These lists of
  /// operands are combined with the AND_NOT operator, so that users represented
  /// by the inclusive operands are included in the user list, minus the users
  /// represented by the exclusive operands.
  GoogleAdsSearchads360V23CommonFlexibleRuleUserListInfo? flexibleRuleUserList;

  /// The status of pre-population.
  ///
  /// The field is default to NONE if not set which means the previous users
  /// will not be considered. If set to REQUESTED, past site visitors or app
  /// users who match the list definition will be included in the list (works on
  /// the Display Network only). This will only add past users from within the
  /// last 30 days, depending on the list's membership duration and the date
  /// when the remarketing tag is added. The status will be updated to FINISHED
  /// once request is processed, or FAILED if the request fails.
  /// Possible string values are:
  /// - "UNSPECIFIED" : Not specified.
  /// - "UNKNOWN" : Used for return value only. Represents value unknown in this
  /// version.
  /// - "REQUESTED" : Prepopoulation is being requested.
  /// - "FINISHED" : Prepopulation is finished.
  /// - "FAILED" : Prepopulation failed.
  core.String? prepopulationStatus;

  GoogleAdsSearchads360V23CommonRuleBasedUserListInfo({
    this.flexibleRuleUserList,
    this.prepopulationStatus,
  });

  GoogleAdsSearchads360V23CommonRuleBasedUserListInfo.fromJson(core.Map json_)
    : this(
        flexibleRuleUserList: json_.containsKey('flexibleRuleUserList')
            ? GoogleAdsSearchads360V23CommonFlexibleRuleUserListInfo.fromJson(
                json_['flexibleRuleUserList']
                    as core.Map<core.String, core.dynamic>,
              )
            : null,
        prepopulationStatus: json_['prepopulationStatus'] as core.String?,
      );

  core.Map<core.String, core.dynamic> toJson() {
    final flexibleRuleUserList = this.flexibleRuleUserList;
    final prepopulationStatus = this.prepopulationStatus;
    return {
      'flexibleRuleUserList': ?flexibleRuleUserList,
      'prepopulationStatus': ?prepopulationStatus,
    };
  }
}

