    final rejectionReason = this.rejectionReason;
    return {
      'amountMicros': ?amountMicros,
      'expirationDateTime': ?expirationDateTime,
      'insuranceDocumentReadonly': ?insuranceDocumentReadonly,
      'rejectionReason': ?rejectionReason,
    };
  }
}

